`timescale 1ns/1ps
// spmv_top_tb.v -- GENERATED by gen_hdl.py. Self-checking testbench.
// Reads the golden results from expected_out_int.hex (run Questa
// from the folder that contains that file) and checks every y[i].
module spmv_top_tb;
    localparam NUM_ROWS = 50;

    reg  clock = 0;
    reg  reset = 1;
    reg  start = 0;
    wire done;
    wire y_valid;
    wire [5:0] y_addr;
    wire signed [31:0] y_out;

    reg [31:0] expected [0:NUM_ROWS-1];
    integer pass_count = 0;
    integer fail_count = 0;

    spmv_top uut (
        .clock   (clock),
        .reset   (reset),
        .start   (start),
        .done    (done),
        .y_valid (y_valid),
        .y_addr  (y_addr),
        .y_out   (y_out)
    );

    always #5 clock = ~clock;   // 100 MHz

    initial begin
        $readmemh("expected_out_int.hex", expected);

        repeat (3) @(posedge clock);
        reset = 0;
        @(posedge clock);

        start = 1;
        @(posedge clock);
        start = 0;

        wait (done == 1);
        #50;
        $display("-------------------------------------------------");
        $display("SUMMARY: %0d PASS, %0d FAIL, out of %0d rows", pass_count, fail_count, NUM_ROWS);
        if (pass_count == NUM_ROWS && fail_count == 0)
            $display("ALL TESTS PASSED");
        else
            $display("TEST FAILED");
        $display("-------------------------------------------------");
        $finish;
    end

    // watchdog: stop if the design never finishes
    initial begin
        #51120;
        $display("TIMEOUT: design did not finish");
        $finish;
    end

    // check each y as it is produced
    always @(posedge clock) begin
        if (y_valid) begin
            if (y_out === expected[y_addr]) begin
                pass_count = pass_count + 1;
                $display("y[%0d] = %h (%0d)  PASS", y_addr, y_out, y_out);
            end else begin
                fail_count = fail_count + 1;
                $display("y[%0d] = %h (%0d)  FAIL (expected %h)", y_addr, y_out, y_out, expected[y_addr]);
            end
        end
    end
endmodule
